<script setup lang="ts">import{ref}from'vue';import{useQuery}from'@tanstack/vue-query';import{api,unwrap}from'../api/client';import type{components}from'../api/generated/voltbridge-schema';const id=ref(''),kind=ref('record'),submitted=ref(false);const q=useQuery({queryKey:['billing',kind,id],enabled:submitted, retry:false,queryFn:async()=>unwrap<components['schemas']['BillingRecordView']>(kind.value==='record'?await api.GET('/api/billing-records/{billingRecordId}',{params:{path:{billingRecordId:id.value}}}):await api.GET('/api/billing-records/by-transaction/{transactionId}',{params:{path:{transactionId:id.value}}}))});function search(){submitted.value=true;q.refetch()}</script>
<template><div class="page"><h1>Billing lookup</h1><el-card><el-form inline @submit.prevent="search"><el-form-item label="Lookup by"><el-select v-model="kind"><el-option label="Billing record ID" value="record"/><el-option label="Transaction ID" value="transaction"/></el-select></el-form-item><el-form-item label="Identifier"><el-input v-model="id" required/></el-form-item><el-button type="primary" @click="search">Look up</el-button></el-form><el-alert v-if="q.isError.value" type="error" :title="q.error.value?.message||'Billing lookup failed'" :closable="false"/><el-skeleton v-else-if="q.isFetching.value" :rows="3" animated/><el-descriptions v-else-if="q.data.value" :column="2" border><el-descriptions-item v-for="(v,k) in q.data.value" :key="k" :label="k">{{v??'—'}}</el-descriptions-item></el-descriptions><el-empty v-else description="Look up a billing record by record ID or transaction ID. The API has no list endpoint."/></el-card></div></template>
